BASE_DISCOUNTS = {
    'student': 0.20,
    'senior': 0.15,
    'regular': 0.00
}

MEMBER_BONUS = {
    'student': 0.05,
    'senior': 0.05,
    'regular': 0.10
}

YEARS_BONUS = {
    'student': 0.05,
    'senior': 0.10,
    'regular': 0.05
}


def calculate_discount(price, user_type, is_member, years_active):
    discount = BASE_DISCOUNTS.get(user_type, 0.0)

    if is_member:
        discount += MEMBER_BONUS.get(user_type, 0.0)
        if years_active > 5:
            discount += YEARS_BONUS.get(user_type, 0.0)

    return price * (1 - discount)
